const fragments: readonly [string, string][] = [["请求签名","Request signature"],["时间戳有效窗口","Timestamp validity window"],["签名密钥","Signing secret"],["接收地址","Receive URL"],["接入详情","Integration details"],["订阅事件","Subscribed events"],["收到短信","SMS received"],["处理策略","Processing strategy"],["自动处理","automatic processing"],["正式联调","production integration"],["接口","API"],["接口说明","API reference"],["上游平台","upstream platform"],["短信","SMS"],["号码","number"],["平台","platform"],["用户","user"],["代理","agent"],["客户","customer"],["库存","inventory"],["商品","product"],["订单","order"],["充值","top-up"],["余额","balance"],["积分","points"],["国家","country"],["服务","service"],["状态","status"],["操作","action"],["原因","reason"],["时间","time"],["日期","date"],["名称","name"],["来源","source"],["目标","target"],["类型","type"],["价格","price"],["数量","quantity"],["天数","days"],["天","days"],["创建","create"],["保存","save"],["查看","view"],["搜索","search"],["选择","select"],["请输入","Enter "],["请选择","Select "],["全部","All "],["暂无","No "],["没有","No "],["正在","Loading "],["已",""],["未","Not "],["失败","failed"],["成功","successful"],["确认","Confirm"],["取消","Cancel"],["启用","Enable"],["禁用","Disable"],["上架","publish"],["下架","unpublish"],["分配","assign"],["释放","release"],["回收","reclaim"],["导入","import"],["同步","sync"],["刷新","refresh"],["管理","management"],["记录","records"],["详情","details"],["信息","information"],["配置","configuration"],["当前","current"],["最近","recent"],["全部","all"],["在线","online"],["离线","offline"],["待","pending"],["异常","exception"],["平台管理员","platform administrator"],["管理员","administrator"]];
export function translateAdminText(source: string): string | undefined {
  if (!adminKeys.has(source)) return undefined;
  if (exact[source]) return exact[source];
  let value = source.replace(/(\d+)\s*个号码/g, '$1 numbers').replace(/(\d+)\s*个/g, '$1 ');
  for (const [from, to] of fragments) value = value.split(from).join(to);
  return value;
}
